public static string CreateSafeSheetName(string nameProposal, char replaceChar)
{
    if (nameProposal == null)
    {
        return "null";
    }
    else if (nameProposal.Length < 1)
    {
        return "empty";
    }
    else
    {
        int length = Math.Min(31, nameProposal.Length);
        string shortenName = nameProposal.Substring(0, length);
        StringBuilder result = new StringBuilder(shortenName);
        for (int i = 0; i < length; i++)
        {
            char ch = result[i];
            switch (ch)
            {
                case '\u0000':
                case '\u0003':
                case ':':
                case '/':
                case '\\':
                case '?':
                case '*':
                case ']':
                case '[':
                    result[i] = replaceChar;
                    break;
                case '\'':
                    if (i == 0 || i == length - 1)
                    {
                        result[i] = replaceChar;
                    }
                    break;
                default:
                    break;
            }
        }
        return result.ToString();
    }
}
```
Note that the `Math.Min` method is used to ensure that the length of the string is not greater than 31 characters. Also, the `StringBuilder` class is used to create a new string with the replaced characters.

