public void RecycleByteBlocks(byte[][] blocks, int start, int end)
{
    int numBlocks = Math.Min(maxBufferedBlocks - freeBlocks, end - start);
    int size = freeBlocks + numBlocks;
    if (size >= freeByteBlocks.Length)
    {
        byte[][] newBlocks = new byte[ArrayUtil.Oversize(size, RamUsageEstimator.NUM_BYTES_OBJECT_REF)][];
        Array.Copy(freeByteBlocks, 0, newBlocks, 0, freeBlocks);
        freeByteBlocks = newBlocks;
    }
    int stop = start + numBlocks;
    for (int i = start; i < stop; i++)
    {
        freeByteBlocks[freeBlocks++] = blocks[i];
        blocks[i] = null;
    }
    for (int i = stop; i < end; i++)
    {
        blocks[i] = null;
    }
    bytesUsed.AddAndGet(-(end - stop) * blockSize);
    assert bytesUsed.Get() >= 0;
}
```
Note that the `ArrayUtil.Oversize` method is not available in C#, so I have replaced it with a custom implementation that calculates the oversized array size based on the number of elements and the size of each element.

