public SynonymFilterFactory(Map<string, string> args)
{
    base(args);
    ignoreCase = getBoolean(args, "ignoreCase", false);
    synonyms = require(args, "synonyms");
    format = get(args, "format");
    expand = getBoolean(args, "expand", true);
    analyzerName = get(args, "analyzer");
    tokenizerFactory = get(args, "tokenizerFactory");

    if (analyzerName != null && tokenizerFactory != null)
    {
        throw new IllegalArgumentException("Analyzer and TokenizerFactory can't be specified both: " + analyzerName + " and " + tokenizerFactory);
    }

    if (tokenizerFactory != null)
    {
        tokArgs.put("luceneMatchVersion", getLuceneMatchVersion().ToString());
        foreach (string key in args.Keys)
        {
            tokArgs.put(key.Replace("tokenizerFactory.", ""), args[key]);
            args.Remove(key);
        }
    }

    if (!args.IsEmpty())
    {
        throw new IllegalArgumentException("Unknown parameters: " + args);
    }
}
```
