public static bool hasSLLConflictTerminatingPrediction(PredictionMode mode, ATNConfigSet configs)
{
    if (allConfigsInRuleStopStates(configs))
    {
        return true;
    }

    if (mode == PredictionMode.SLL && configs.HasSemanticContext)
    {
        ATNConfigSet dup = new ATNConfigSet();
        foreach (ATNConfig c in configs)
        {
            c = new ATNConfig(c, SemanticContext.NONE);
            dup.Add(c);
        }
        configs = dup;
    }

    Collection<BitSet> altsets = getConflictingAltSubsets(configs);
    bool heuristic = hasConflictingAltSet(altsets) && !hasStateAssociatedWithOneAlt(configs);
    return heuristic;
}

