public IntervalSet[] GetDecisionLookahead(ATNState s)
{
    if (s == null)
    {
        return null;
    }

    IntervalSet[] look = new IntervalSet[s.NumberOfTransitions()];
    for (int alt = 0; alt < s.NumberOfTransitions(); alt++)
    {
        look[alt] = new IntervalSet();
        HashSet<ATNConfig> lookBusy = new HashSet<ATNConfig>();
        bool seeThruPreds = false;
        _LOOK(s.Transition(alt).Target, null, PredictionContext.EMPTY, look[alt], lookBusy, new BitSet(), seeThruPreds, false);
        if (look[alt].Count == 0 || look[alt].Contains(HIT_PRED))
        {
            look[alt] = null;
        }
    }

    return look;
}
