    int maxRow = Math.Max(_firstCell.Row, _lastCell.Row);
    int minCol = Math.Min(_firstCell.Column, _lastCell.Column);
    int maxCol = Math.Max(_firstCell.Column, _lastCell.Column);

    string sheetName = _firstCell.SheetName;
    List<CellReference> refs = new List<CellReference>();

    for (int row = minRow; row <= maxRow; row++)
    {
        for (int col = minCol; col <= maxCol; col++)
        {
            CellReference ref = new CellReference(sheetName, row, col, _firstCell.IsRowAbsolute, _firstCell.IsColumnAbsolute);
            refs.Add(ref);
        }
    }

    return refs.ToArray();
}
