public static string CreateSafeSheetName(string nameProposal, char replaceChar)
{
    if (string.IsNullOrEmpty(nameProposal))
    {
        return "null";
    }

    int length = Math.Min(31, nameProposal.Length);
    string shortenname = nameProposal.Substring(0, length);
    char[] result = shortenname.ToCharArray();

    for (int i = 0; i < length; i++)
    {
        char ch = result[i];
        switch (ch)
        {
            case '\u0000':
            case '\u0003':
            case ':':
            case '/':
            case '\\':
            case '?':
            case '*':
            case ']':
            case '[':
                result[i] = replaceChar;
                break;
            case '\'':
                if (i == 0 || i == length - 1)
                {
                    result[i] = replaceChar;
                }
                break;
        }
    }

    return new string(result);
}
```

Note: The main differences between the Java and C# versions are:

- In C#, we use `string.IsNullOrEmpty` to check for null or empty strings.
- In C#, we use `ToCharArray()` to convert a string to a character array, which is mutable.
- In C#, we use `new string(result)` to convert the character array back to a string.
- In C#, we use `char[]` instead of `StringBuilder` because we are not modifying the string in place, but rather replacing individual characters in the array.

