    if (collectPredicates && inContext)
    {
        if (fullCtx)
        {
            int currentPosition = _input.Index;
            _input.Seek(_startIndex);
            bool predSucceeds = EvalSemanticContext(pt.Predicate, _outerContext, config.Alt, fullCtx);
            _input.Seek(currentPosition);
            if (predSucceeds)
