        RuleTransition rt = (RuleTransition)invokingState.Transition(0);
        following = NextTokens(rt.FollowState);
        expected.UnionWith(following);
        expected.Remove(Token.EPSILON);
        ctx = ctx.Parent;
    }

    if (following.Contains(Token.EPSILON))
