public SynonymFilterFactory(Dictionary<string, string> args) : base(args)
{
    ignoreCase = getBoolean(args, "ignoreCase", false);
    synonyms = require(args, "synonyms");
    format = get(args, "format");
    expand = getBoolean(args, "expand", true);
    analyzerName = get(args, "analyzer");
    tokenizerFactory = get(args, "tokenizerFactory");

    if (analyzerName!= null && tokenizerFactory!= null)
    {
        throw new ArgumentException("Analyzer and TokenizerFactory can't be specified both: " + analyzerName + " and " + tokenizerFactory);
    }

    if (tokenizerFactory!= null)
    {
        tokArgs.Add("luceneMatchVersion", getLuceneMatchVersion().ToString());
        foreach (var key in args.Keys.ToList())
        {
            if (!key.StartsWith("tokenizerFactory."))
            {
                tokArgs.Add(key, args[key]);
            }
            else
            {
                args.Remove(key);
            }
        }
    }

    if (args.Count > 0)
    {
        throw new ArgumentException("Unknown parameters: " + string.Join(", ", args.Keys));
    }
}
```

