```csharp
public SynonymFilterFactory(Dictionary<string, string> args)
{
    base(args);
    ignoreCase = GetBoolean(args, "ignoreCase", false);
    synonyms = Require(args, "synonyms");
    format = Get(args, "format");
    expand = GetBoolean(args, "expand", true);
    analyzerName = Get(args, "analyzer");
    tokenizerFactory = Get(args, "tokenizerFactory");

    if (!string.IsNullOrEmpty(analyzerName) &&!string.IsNullOrEmpty(tokenizerFactory))
    {
        throw new ArgumentException("Analyzer and TokenizerFactory cannot be specified both: " + analyzerName + " and " + tokenizerFactory);
    }

    if (!string.IsNullOrEmpty(tokenizerFactory))
    {
        var luceneMatchVersion = GetLuceneMatchVersion();
        var tokArgs = new Dictionary<string, string>();
        tokArgs.Add("luceneMatchVersion", luceneMatchVersion.ToString());

        foreach (var key in args.Keys.ToList())
        {
            if (!key.StartsWith("tokenizerFactory."))
            {
                tokArgs.Add(key, args[key]);
                args.Remove(key);
            }
        }
    }

    if (args.Count > 0)
    {
        throw new ArgumentException("Unknown parameters: " + string.Join(", ", args.Select(x => x.Key + "=" + x.Value)));
    }
}
```

