int checkExternSheet(int firstSheetIndex, int lastSheetIndex) {
    int thisWbIndex = -1;
    for (int i = 0; i < _externalBookBlocks.Length; i++) {
        SupBookRecord ebr = _externalBookBlocks[i].ExternalBookRecord;
        if (ebr.IsInternalReferences()) {
            thisWbIndex = i;
            break;
        }
    }
    if (thisWbIndex < 0) {
        throw new System.Runtime.InteropServices.MarshalException("Could not find 'internal references' EXTERNALBOOK");
    }
    int i = _externSheetRecord.GetRefIxForSheet(thisWbIndex, firstSheetIndex, lastSheetIndex);
    if (i >= 0) {
        return i;
    }
    return _externSheetRecord.AddRef(thisWbIndex, firstSheetIndex, lastSheetIndex);
}

