public ATNConfig precedenceTransition(ATNConfig config, PrecedencePredicateTransition pt, bool collectPredicates, bool inContext, bool fullCtx)
{
    if (debug)
    {
        System.out.WriteLine("PRED (collectPredicates=" + collectPredicates + ") " + pt.precedence + ">=_p" + ", ctx dependent=true");
        if (parser != null)
        {
            System.out.WriteLine("context surrounding pred is " + parser.getRuleInvocationStack());
        }
    }

    ATNConfig c = null;

    if (collectPredicates && inContext)
    {
        if (fullCtx)
        {
            int currentPosition = _input.Index;
            _input.Seek(_startIndex);
            bool predSucceeds = evalSemanticContext(pt.GetPredicate(), _outerContext, config.alt, fullCtx);
            _input.Seek(currentPosition);
            if (predSucceeds)
            {
                c = new ATNConfig(config, pt.Target);
            }
        }
        else
        {
            SemanticContext newSemCtx = SemanticContext.And(config.semanticContext, pt.GetPredicate());
            c = new ATNConfig(config, pt.Target, newSemCtx);
        }
    }
    else
    {
        c = new ATNConfig(config, pt.Target);
    }

    if (debug)
    {
        System.out.WriteLine("config from pred transition=" + c);
    }

    return c;
}
