{
    ignoreCase = getBoolean(args, "ignoreCase", false);
    synonyms = require(args, "synonyms");
    format = get(args, "format");
    expand = getBoolean(args, "expand", true);
    analyzerName = get(args, "analyzer");
    tokenizerFactory = get(args, "tokenizerFactory");

    if (analyzerName != null && tokenizerFactory != null)
    {
        throw new ArgumentException($"Analyzer and TokenizerFactory can't be specified both: {analyzerName} and {tokenizerFactory}");
    }

    if (tokenizerFactory != null)
    {
        tokArgs.Add("luceneMatchVersion", getLuceneMatchVersion().ToString());
        foreach (string key in args.Keys.ToList())
        {
            string newKey = key.Replace("^tokenizerFactory\\.", "");
            tokArgs.Add(newKey, args[key]);
            args.Remove(key);
        }
    }

    if (args.Count > 0)
    {
        throw new ArgumentException($"Unknown parameters: {string.Join(", ", args.Keys)}");
    }
}

private bool getBoolean(Dictionary<string, string> args, string key, bool defaultValue)
{
    if (args.TryGetValue(key, out string value))
    {
        return bool.Parse(value);
    }
    return defaultValue;
}

private string get(Dictionary<string, string> args, string key)
{
    if (args.TryGetValue(key, out string value))
    {
        return value;
    }
    return null;
}

private T require<T>(Dictionary<string, string> args, string key)
{
    if (args.TryGetValue(key, out string value))
    {
        return (T)Convert.ChangeType(value, typeof(T));
    }
    throw new ArgumentException($"Missing required parameter: {key}");
}

